sys_script_include.script:
var nspro_task = Class.create();
nspro_task.prototype = {
    initialize: function() {
        this.nsProCore = new x_g_sonc_ns_pro.core_nspro();
        var currentScopeID = gs.getCurrentApplicationId();
        var grScope = new GlideRecord('sys_app');
        this.CLASSNAME = this.nsProCore.getClassName(currentScopeID, this.type);

    },
    _hasLocalCircuitAssignments(hostCirSysID, siteSysID, telcoOrder) {
        var hasLocalCircuits = false;
        var queryString = 'x_g_sonc_ns_pro_site.sys_id=' + siteSysID;

        if (hostCirSysID) {
            queryString = queryString + '^x_g_sonc_ns_pro_pe_host_circuit_id.sys_id=' + hostCirSysID;
        }

        if (telcoOrder) {
            queryString = queryString + '^x_g_sonc_ns_pro_network_request.sys_id=' + telcoOrder;
        }

        var localCircuits = new GlideRecord('cmdb_ci_network_circuit');
        localCircuits.addQuery('x_g_sonc_ns_pro_host_ckt', false);
        localCircuits.addEncodedQuery(queryString);
        localCircuits.setLimit(1);
        localCircuits.query();

        if (localCircuits.next()) {
            hasLocalCircuits = true;
        }
        return hasLocalCircuits;

    },
    _hasPortAssignments: function(site, hostCir, localCir) {
        var hasPortsAssigned = false;
        var queryString = 'site=' + site;

        if (hostCir) {
            queryString = queryString + '^pe_host_circuit_id=' + hostCir;
        }
        if (localCir) {
            queryString = queryString + '^local_circuit_id=' + localCir;
        }

        var portRecord = new GlideRecord('x_g_sonc_ns_pro_port');
        portRecord.addEncodedQuery(queryString);
        portRecord.setLimit(1);
        portRecord.query();

        if (portRecord.next()) {
            hasPortsAssigned = true;
        }

        return hasPortsAssigned;

    },
    _getLocalCircuitsList: function(site, hostCir, telcoOrder) {
        var localCircuitArray = [];
        var queryString = 'x_g_sonc_ns_pro_site=' + site + '^x_g_sonc_ns_pro_host_ckt=false';

        if (hostCir) {
            queryString = queryString + '^x_g_sonc_ns_pro_pe_host_circuit_id=' + hostCir;
        }

        if (telcoOrder) {
            queryString = queryString + '^x_g_sonc_ns_pro_network_request=' + telcoOrder;
        }

        var localCircuits = new GlideRecord('cmdb_ci_network_circuit');
        //(queryString);
        localCircuits.addEncodedQuery(queryString);
        localCircuits.query();

        while (localCircuits.next()) {
            localCircuitArray.push(localCircuits.getValue('sys_id') + '');
        }

        return localCircuitArray.join(',');

    },
    _getAssignedPortList: function(site, hostCir, localCir) {
        var portsArray = [];
        var queryString = 'site=' + site;

        if (hostCir) {
            queryString = queryString + '^pe_host_circuit_id=' + hostCir;
        }
        if (localCir) {
            queryString = queryString + '^local_circuit_id=' + localCir;
        }

        var portRecord = new GlideRecord('x_g_sonc_ns_pro_port');
        portRecord.addEncodedQuery(queryString);
        gs.info(queryString);
        portRecord.query();

        while (portRecord.next()) {
            portsArray.push(portRecord.getValue('sys_id') + '');
        }

        return portsArray.join(',');
    },
    getTaskInformation: function(taskSysID) {
        var errorString = '';
        var response = {};

        try {
            var taskRecord = new GlideRecord('x_g_sonc_ns_pro_nspro_tasks');
            if (taskRecord.get(taskSysID)) {
                var circuit = taskRecord.getValue('circuit');
                var site = taskRecord.getValue('site');
                var telcoOrder = taskRecord.getValue('telco_order');
                var requestedHA = false;
                if (taskRecord.getElement('telco_order.request_ha').toString() == "true") {
                    requestedHA = true;
                }
                response.sys_id = taskRecord.getValue('sys_id');
                response.number = taskRecord.getValue('number');
                response.telco_order = taskRecord.getValue('telco_order');
                response.site = site;
                response.telco_provider = taskRecord.getValue('telco_provider');
                response.circuit = circuit;
                response.previous_circuit = '';
                response.hasLocalCircuits = this._hasLocalCircuitAssignments(null, site, telcoOrder);
                response.hasPortAssignments = this._hasPortAssignments(site, circuit);
                response.requestedHA = requestedHA;
                response.siteZipCode = taskRecord.getElement('location.zip').toString();


            }
            response.message = 'success';
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }

        return response;
    },
    taskHostCircuitChanged: function(taskInformation) {
        var errorString = '';
        var response = {};

        try {
            gs.info("has port assignments " + taskInformation.hasPortAssignments);
            if (taskInformation.hasPortAssignments) {
                var ports = this._getAssignedPortList(taskInformation.site, taskInformation.previous_circuit, null);
                gs.info('going to remove ports: ' + ports);
                var nsProPort = new x_g_sonc_ns_pro.port();

                var removePortResponse = nsProPort.removePortsFromSite(taskInformation.site, ports);
                if (removePortResponse.message.startsWith('Error Occured ')) {
                    throw new Error(removePortResponse.message);
                }
            }

            if (taskInformation.hasLocalCircuits) {
                var localCircuits = this._getLocalCircuitsList(taskInformation.site, null, taskInformation.telco_order);
                var localCircuitActionResponse;
                //gs.info("local circuits found " + localCircuits);
                var nsProCircuit = new x_g_sonc_ns_pro.circuit();

                var reAssignLocalCircuits = true;


                if (reAssignLocalCircuits == true) {
                    localCircuitActionResponse = nsProCircuit.reAssignLocalCircuitHostAssociations(localCircuits, taskInformation.circuit);
                } else {
                    localCircuitActionResponse = nsProCircuit.removeLocalCircuitHostAssociations(localCircuits);
                }


                if (localCircuitActionResponse.message.startsWith('Error Occured ')) {
                    throw new Error(localCircuitActionResponse.message);
                }
            }
            response.message = "Successfully removed associated items";

        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            gs.info(errorString);
            response.message = errorString;
        }

        return response;

    },
    taskTelcoProviderChanged: function(taskInformation) {
        var errorString = '';
        var response = {};

        try {
            if (taskInformation.hasPortAssignments) {
                var ports = this._getAssignedPortList(taskInformation.site, taskInformation.circuit);
                var nsProPort = new x_g_sonc_ns_pro.port();

                var removePortResponse = nsProPort.removePortsFromSite(taskInformation.site, ports);
                if (removePortResponse.message.startsWith('Error Occured ')) {
                    throw new Error(removePortResponse.message);
                }
            }

            if (taskInformation.hasLocalCircuits) {
                var localCircuits = this._getLocalCircuitsList(taskInformation.site, taskInformation.circuit, taskInformation.telco_order);
                gs.info("local circuits found " + localCircuits);
                var nsProCircuit = new x_g_sonc_ns_pro.circuit();

                var removeCircuitResponse = nsProCircuit.removeLocalCircuits(localCircuits);
                if (removeCircuitResponse.message.startsWith('Error Occured ')) {
                    throw new Error(removeCircuitResponse.message);
                }
            }
            response.message = "Successfully removed associated items";

        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            gs.info(errorString);
            response.message = errorString;
        }

        return response;

    },
    setNewSiteToInstalled: function(task) {
        var errorString = '';
        var response = {};

        try {
            //set site to installed.
            var site = task.getValue('site');
            var siteRecord = new GlideRecord('cmdb_ci_site');
            if (siteRecord.get(site)) {
                siteRecord.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                siteRecord.update();
            } else {
                throw new Error("Site could not be updated.  Not found");
            }

            //set local circuits to installed.
            var circuitArray = [];
            var hostCircuit = task.getValue('circuit');
            var networkRequest = task.getValue('telco_order');
            var netCircuit = new GlideRecord('cmdb_ci_network_circuit');
            netCircuit.addQuery('x_g_sonc_ns_pro_pe_host_circuit_id', hostCircuit);
            netCircuit.addQuery('x_g_sonc_ns_pro_site', site);
            netCircuit.addQuery('x_g_sonc_ns_pro_network_request', networkRequest);
            netCircuit.query();

            while (netCircuit.next()) {
                netCircuit.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                netCircuit.update();
                circuitArray.push(netCircuit.getValue('sys_id') + '');
            }

            //set ports to installed
            var netGearArray = [];
            var portRecords = new GlideRecord('x_g_sonc_ns_pro_port');
            portRecords.addQuery('site', site);
            portRecords.addQuery('local_circuit_id', 'IN', circuitArray.join(','));
            portRecords.query();

            while (portRecords.next()) {
                portRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                portRecords.update();

                if (portRecords.getValue('network_gear') != '') {
                    netGearArray.push(portRecords.getValue('network_gear') + '');
                }
            }

            //set all netgear to installed.
            var netGearRecords = new GlideRecord('cmdb_ci_netgear');
            netGearRecords.addQuery('sys_id', 'IN', netGearArray.join(','));
            netGearRecords.query();

            while (netGearRecords.next()) {
                netGearRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                //gs.info('WOULD UPDATE: ' + netGearRecords.getValue('name'));
                netGearRecords.update();
            }
            response.message = "Successfully set all Task Items to Installed."

        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            gs.info(errorString);
            response.message = errorString;
        }
        return response;
    },
    setSiteItemsToRetire: function(task) {
        var errorString = '';
        var response = {};

        try {
            //set site to pending retire.
            var site = task.getValue('site');
            var siteRecord = new GlideRecord('cmdb_ci_site');
            if (siteRecord.get(site)) {
                siteRecord.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.RETIRED);
                siteRecord.update();
            } else {
                throw new Error("Site could not be updated.  Not found");
            }

            //set local circuits to pending retire.
            var circuitArray = [];
            var netCircuit = new GlideRecord('cmdb_ci_network_circuit');
            netCircuit.addQuery('x_g_sonc_ns_pro_host_ckt', false);
            netCircuit.addQuery('x_g_sonc_ns_pro_site', site);
            netCircuit.query();

            while (netCircuit.next()) {
                netCircuit.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.RETIRED);
                netCircuit.update();
                circuitArray.push(netCircuit.getValue('sys_id') + '');
            }

            //set ports to pending retire
            var netGearArray = [];
            var portRecord = new GlideRecord('x_g_sonc_ns_pro_port');
            portRecord.addQuery('site', site);
            portRecord.addQuery('local_circuit_id', 'IN', circuitArray.join(','));
            portRecord.query();

            while (portRecord.next()) {
                var portVLan = portRecord.getValue('remote_site_circuit_vlan');
                var portIPAddress = portRecord.getValue('ip_address');
                if (portIPAddress.startsWith('172.22.')) {
                    portRecord.setValue('install_status', NSPROConstants.PORT_STATUS.UNASSIGNED);
                    portRecord.setValue('local_circuit_id', gs.nil());
                    portRecord.setValue('network_gear', gs.nil());
                    portRecord.setValue('name', '');
                    portRecord.setValue('vrf', '');
                    portRecord.setValue('site', gs.nil());
                } else {
                    portRecord.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.RETIRED);
                }
                portRecord.update();

                if (portRecord.getValue('network_gear') != '') {
                    netGearArray.push(portRecord.getValue('network_gear') + '');
                }
            }

            //set all netgear to pending retire.
            var netGearRecords = new GlideRecord('cmdb_ci_netgear');
            netGearRecords.addQuery('sys_id', 'IN', netGearArray.join(','));
            netGearRecords.query();

            while (netGearRecords.next()) {
                netGearRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.RETIRED);
                //gs.info('WOULD UPDATE: ' + netGearRecords.getValue('name'));
                netGearRecords.update();
            }
            response.message = "Successfully set all Task Items to retire.";

        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            gs.info(errorString);
            response.message = errorString;
        }
        return response;
    },
    type: 'nspro_task'
};
